head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.ssMarket = "N"; // 시장 콤보 초기 세팅 완료 여부(초기 setValue 시 onchange 재조회 방지)
scwin.skw = ""; // 제출인명 필터 키워드
scwin.tpcd = ""; // 세션의 시장구분 (onpageload 에서 부모 화면 값 취득)

///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★
스크립트 수작업 유의사항

*/
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 부모 화면의 시장구분(js_com_market)을 취득하고 시장구분 공통코드 조회(code1Sync)를 수행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = async function () {
    try {
        // 구 최상위 즉시 실행($c.win.getParent().js_com_market) 이동 — 부모 화면 부재 가드
        scwin.tpcd = $c.win.getParent()?.js_com_market ?? "";
        await scwin.code1Sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00008.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시 처리(현재 처리 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function () {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name combo_market_onselchange
 * @description 시장구분 콤보 변경 — 초기 세팅 완료(ssMarket=Y) 후에만 제출인 목록을 재조회한다(listSync).
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.combo_market_onselchange(info);
 */
scwin.combo_market_onselchange = async function (info) {
    try {
        if (scwin.ssMarket === "Y") {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00008.combo_market_onselchange" });
    }
};

/**
 * @method
 * @name img_search_onclick
 * @description [조회] 버튼 클릭 — 입력한 제출인명 접두 위치로 이동한다(JongmokName).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.img_search_onclick(e);
 */
scwin.img_search_onclick = function (e) {
    try {
        scwin.JongmokName();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00008.img_search_onclick" });
    }
};

/**
 * @method
 * @name txb_jongmokName_onkeydown
 * @description 제출인명 입력란 키다운 — Enter 키 입력 시 제출인명 접두 위치로 이동한다(JongmokName).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.txb_jongmokName_onkeydown(e);
 */
scwin.txb_jongmokName_onkeydown = function (e) {
    try {
        if (Number(e.keyCode) === 13) {
            scwin.JongmokName();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00008.txb_jongmokName_onkeydown" });
    }
};

/**
 * @method
 * @name grd_jongmok_onkeydown
 * @description 목록 그리드 키다운 — Enter 키 입력 시 선택 행 제출인 정보를 부모창으로 전달한다(Confirm).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.grd_jongmok_onkeydown(e);
 */
scwin.grd_jongmok_onkeydown = async function (e) {
    try {
        if (Number(e.keyCode) === 13) {
            await scwin.Confirm();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00008.grd_jongmok_onkeydown" });
    }
};

/**
 * @method
 * @name grd_jongmok_oncelldblclick
 * @description 목록 행 더블클릭 — 선택 행 제출인 정보를 부모창으로 전달한다(Confirm).
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 컬럼 인덱스
 * @param {String} columnId 컬럼 ID
 * @returns {void}
 * @hidden N
 * @example scwin.grd_jongmok_oncelldblclick(0, 0, "SUBMIT_OBLG_ABBRV");
 */
scwin.grd_jongmok_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.Confirm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00008.grd_jongmok_oncelldblclick" });
    }
};

