/**
 * @method
 * @name dts_jongmok_OnFilter
 * @description 회사약명·이전상호약명 키워드 필터 — 구 Gauce UseFilter/Filter()/OnFilter 대체.
 * @returns {void}
 * @hidden N
 * @example scwin.dts_jongmok_OnFilter();
 */
scwin.dts_jongmok_OnFilter = function () {
    try {
        dts_jongmok.removeColumnFilterAll();

        if (scwin.skw !== "") {
            dts_jongmok.setColumnFilter({ type : "row", colIndex : "COM_ABBRV", key : scwin.skw, condition : "and", exactMatch : false });
            dts_jongmok.setColumnFilter({ type : "row", colIndex : "OLD_COM_ABBRV", key : scwin.skw, condition : "or", exactMatch : false });
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00008.dts_jongmok_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 제출인 목록 조회 — 조회 후 정렬·필터 반영(구 SortExpr/Sort·dts_jongmok_OnLoadCompleted 대체).
 * @returns {void}
 * @hidden N
 * @example await scwin.listSync();
 */
scwin.listSync = async function () {
    txb_jongmokName.setValue("");
    scwin.skw = "";
    const sbmOptions = {
        id : "sbm_dts_jongmok",
        action : "/submitperson.do?method=searchSubmitPerson&DISCLS_SUBMITPRN_TP_CD=" + encodeURIComponent(combo_market.getValue() ?? ""), // 시장구분 필터(원본 ui 확인)
        ref : "",
        target : "dts_jongmok=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    dts_jongmok.sort("SUBMIT_OBLG_ABBRV", 0);
    scwin.dts_jongmok_OnFilter();
    grd_jongmok.setFocusedCell(0, 0);
};

/**
 * @method
 * @name code1Sync
 * @description 시장구분 공통코드 조회 — 조회 후 콤보 세팅·목록 조회(구 MxDataSet_code1_OnLoadCompleted 대체).
 * @returns {void}
 * @hidden N
 * @example await scwin.code1Sync();
 */
scwin.code1Sync = async function () {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    scwin.marketSetCombo();
    if (MxDataSet_code1.getRowCount() > 0) {
        await scwin.listSync();
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name Jongmok
 * @description 가나다라.. 검색 — 구 countrow/NameValue/Rowposition(Gauce) 을 getRowCount/getCellData/setFocusedCell 로 대체.
 * @param {String} prevval 구간 시작 문자(포함)
 * @param {String} nextval 구간 종료 문자(미포함)
 * @returns {void}
 * @hidden N
 * @example scwin.Jongmok('가', '나');
 */
scwin.Jongmok = function (prevval, nextval) {
    txb_jongmokName.setValue("");
    scwin.skw = "";
    scwin.dts_jongmok_OnFilter();
    dts_jongmok.sort("SUBMIT_OBLG_ABBRV", 0);

    let cnt = 0;
    for (let i = 0; i < dts_jongmok.getRowCount(); i++) {
        const name = String(dts_jongmok.getCellData(i, "SUBMIT_OBLG_ABBRV")).substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }

    // 구 Rowposition = cnt+11 → cnt (스크롤 확보) 트릭 대체
    grd_jongmok.setFocusedCell(Math.min(cnt + 11, Math.max(dts_jongmok.getRowCount() - 1, 0)), 0);
    grd_jongmok.setFocusedCell(cnt, 0);
    grd_jongmok.setFocus();
};

/**
 * @method
 * @name JongmokName
 * @description 제출인명 접두 위치 탐색 — 입력 문자열 이상인 첫 행으로 포커스를 이동한다.
 * @returns {void}
 * @hidden N
 * @example scwin.JongmokName();
 */
scwin.JongmokName = function () {
    dts_jongmok.sort("SUBMIT_OBLG_ABBRV", 0);

    let cnt = 0;
    const txtVal = txb_jongmokName.getValue().toUpperCase();
    const len = txtVal.length;
    for (let i = 0; i < dts_jongmok.getRowCount(); i++) {
        const name = String(dts_jongmok.getCellData(i, "SUBMIT_OBLG_ABBRV")).substring(0, len).toUpperCase();
        if (txtVal <= name) {
            cnt = i;
            break;
        }
    }

    grd_jongmok.setFocusedCell(Math.min(cnt + 11, Math.max(dts_jongmok.getRowCount() - 1, 0)), 0);
    grd_jongmok.setFocusedCell(cnt, 0);
};

/**
 * @method
 * @name JongmokSearch
 * @description 키워드 필터 검색 — 구 $c.stockSearch.JongmokSearch(미정의 네임스페이스 TypeError) 를 scwin 으로 교정.
 * @returns {void}
 * @hidden N
 * @example scwin.JongmokSearch();
 */
scwin.JongmokSearch = function () {
    scwin.skw = txb_jongmokName.getValue();
    scwin.dts_jongmok_OnFilter();
    grd_jongmok.setFocusedCell(0, 0);
};

/**
 * @method
 * @name Confirm
 * @description 부모창으로 제출인 정보 전달 — 구 RowPosition/NameValue(Gauce) 대체.
 * @returns {void}
 * @hidden N
 * @example await scwin.Confirm();
 */
scwin.Confirm = async function () {
    const row = dts_jongmok.getRowPosition();
    if (row < 0) {
        return;
    }
    const pJongCode = dts_jongmok.getCellData(row, "SUBMIT_OBLG_ABBRV");
    const pJongNm = dts_jongmok.getCellData(row, "DISCLS_SUBMITPRN_TP_CD_NM");
    $c.cm.submitSearch_Rtn(pJongCode, pJongNm);

    await $c.win.closePopup();
};

/**
 * @method
 * @name marketSetCombo
 * @description 시장 콤보 초기 세팅 — 구 주석 처리 marketSetCombo 를 WebSquare API 로 복원.
 * @returns {void}
 * @hidden N
 * @example scwin.marketSetCombo();
 */
scwin.marketSetCombo = function () {
    if (scwin.tpcd !== "") {
        combo_market.setValue(scwin.tpcd);
    }
    scwin.ssMarket = "Y";
};
